const robot = require('./');

// Test getActiveIME
const ime = robot.getActiveIME();
console.log('[test] Active IME:', JSON.stringify(ime));

console.log('[test] Will type in 3 seconds... Focus the target window now!');

setTimeout(() => {
  const ime = robot.getActiveIME();
  console.log('[test] IME at typing time:', JSON.stringify(ime));

  if (ime.isThirdParty) {
    console.log('[test] Third-party IME detected, using PostMessage (default)');
  } else {
    console.log('[test] Microsoft/no IME, using PostMessage (default)');
  }

  robot.typeString("PostMsg你好");
  console.log('[test] Done.');
}, 3000);
